SET client_encoding TO 'UTF8';
-- Cu Chi: 12 panorama 360 thuc te tu chuyen di (Ben Duoc) + anh bo sung
-- Sinh tu BE/docs/scripts/cu_chi_assets.py — DATA ONLY (khong doi schema).
-- FE static: /media/cu-chi/panoramas/<slug>.jpg, /media/cu-chi/gallery/<slug>-N.jpg

-- 0) Don pano thua tu seed truoc (tuyen gio chi con 7 diem) — data only
DELETE FROM hotspots WHERE panorama_id IN ('22222222-2222-2222-2222-222222222228', '22222222-2222-2222-2222-222222222229', '22222222-2222-2222-2222-22222222222a', '22222222-2222-2222-2222-22222222222b', '22222222-2222-2222-2222-22222222222c');
DELETE FROM hotspots WHERE type = 'scene' AND content_ref IN ('22222222-2222-2222-2222-222222222228', '22222222-2222-2222-2222-222222222229', '22222222-2222-2222-2222-22222222222a', '22222222-2222-2222-2222-22222222222b', '22222222-2222-2222-2222-22222222222c');
DELETE FROM panoramas WHERE id IN ('22222222-2222-2222-2222-222222222228', '22222222-2222-2222-2222-222222222229', '22222222-2222-2222-2222-22222222222a', '22222222-2222-2222-2222-22222222222b', '22222222-2222-2222-2222-22222222222c');

-- 1) Panorama: cap nhat 5 scene cu + them 2 scene moi (uuid_last 6,7)
UPDATE panoramas SET image_url = '/media/cu-chi/panoramas/bai-xe-so-1.jpg', title = 'Bãi gửi xe gắn máy số 1' WHERE id = '22222222-2222-2222-2222-222222222221';
UPDATE panoramas SET image_url = '/media/cu-chi/panoramas/den-ben-duoc.jpg', title = 'Đền tưởng niệm Liệt sĩ Bến Dược' WHERE id = '22222222-2222-2222-2222-222222222222';
UPDATE panoramas SET image_url = '/media/cu-chi/panoramas/bo-tu-lenh.jpg', title = 'Căn cứ Bộ Tư lệnh Quân khu Sài Gòn - Gia Định' WHERE id = '22222222-2222-2222-2222-222222222223';
UPDATE panoramas SET image_url = '/media/cu-chi/panoramas/khu-trung-bay.jpg', title = 'Khu trưng bày' WHERE id = '22222222-2222-2222-2222-222222222224';
UPDATE panoramas SET image_url = '/media/cu-chi/panoramas/khu-uy.jpg', title = 'Căn cứ Khu ủy Quân khu Sài Gòn - Gia Định' WHERE id = '22222222-2222-2222-2222-222222222225';

-- 2) Scene-link hotspots noi lo trinh (1<->2<->...<->12)
-- Lam sach scene-link cu de tuyen 12 diem khong bi roi (chi xoa type='scene', khong dung info/quest).
DELETE FROM hotspots WHERE type = 'scene' AND panorama_id IN ('22222222-2222-2222-2222-222222222221', '22222222-2222-2222-2222-222222222222', '22222222-2222-2222-2222-222222222223', '22222222-2222-2222-2222-222222222224', '22222222-2222-2222-2222-222222222225', '22222222-2222-2222-2222-222222222226', '22222222-2222-2222-2222-222222222227');

-- 3) Anh bo sung: hotspot_contents + info hotspots dat quanh moi scene
-- Don info 'supp:%' cu tu seed truoc (giu lai quest 'hotspot:kitchen/vent').
DELETE FROM hotspots WHERE type = 'info' AND content_ref LIKE 'supp:%' AND panorama_id IN ('22222222-2222-2222-2222-222222222221', '22222222-2222-2222-2222-222222222222', '22222222-2222-2222-2222-222222222223', '22222222-2222-2222-2222-222222222224', '22222222-2222-2222-2222-222222222225', '22222222-2222-2222-2222-222222222226', '22222222-2222-2222-2222-222222222227');
